{
  "groups": [
    {
      "group_id": "low_rate_shock",
      "rule": "rate_type == 'fixed' and origination_year <= 2021 and mortgage_rate_pct < 3.0",
      "rationale": "Borrowers with low fixed rates from the pandemic era are highly rate-sensitive and will face significant payment shocks upon renewal."
    },
    {
      "group_id": "vulnerable_renters",
      "rule": "occupancy_type == 'rental' and household_income_cad < 75000",
      "rationale": "Rental property owners with lower household income have less flexibility to absorb rising costs and are more likely to exit the market if yields turn negative."
    },
    {
      "group_id": "strained_families",
      "rule": "n_children >= 3 and household_income_cad < 100000",
      "rationale": "Large households with limited income face substantial inflationary pressure on daily essentials, increasing the risk of default or liquidity-driven refinancing."
    },
    {
      "group_id": "credit_constrained_variable",
      "rule": "rate_type == 'variable' and credit_score_band in ['below_600', '600_659']",
      "rationale": "Borrowers with variable rates and weaker credit scores are the most vulnerable to payment increases and have the fewest alternatives for refinancing."
    },
    {
      "group_id": "equity_rich_prime",
      "rule": "credit_score_band == '720_plus' and insured_flag == False and has_investments == True",
      "rationale": "High-credit borrowers without mortgage insurance have the most bargaining power and are the most likely to switch lenders for competitive rates."
    },
    {
      "group_id": "recent_buyer_stress",
      "rule": "origination_year == 2022 and mortgage_rate_pct > 5.0",
      "rationale": "Borrowers who entered the market at the peak of recent rates are already dealing with high payments and potential negative equity due to market corrections."
    },
    {
      "group_id": "senior_fixed_income",
      "rule": "primary_borrower_age >= 60 and employment_status == 'retired'",
      "rationale": "Retired borrowers living on fixed incomes are less sensitive to interest rate fluctuations but prioritize stability and predictable cash flow."
    }
  ]
}
